use moloch_live_runtime::{execution_distribution::*,dispatch::DispatchLog,feedback};
use moloch_replay::session::Session;
use baal_transport_service::{Receipt,RequestSpec};
use serde_json::{Value,json};
use std::path::PathBuf;
const BASE:u64=1_792_022_400_000;
fn stamp(ms:u64)->String{chrono::DateTime::from_timestamp_millis((BASE+ms)as i64).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true)}
fn config()->Config{Config{markout_ms:1000,post_window_ms:500,maximum_book_age_ms:10_000,maximum_delivery_ms:1000,block_ms:10_000,minimum_blocks:2,minimum_completed:2,retained_samples:16,maximum_pending:32,shrinkage_strength:4,minimum_value_coverage_bps:9000,uncertainty_floor_per_share:1000,tail_charge_per_filled_share:500,write_charge_per_order:100,capital_charge_per_million_unit_ms:1,fee_policy_source_sha256:"a".repeat(64),exit_fee_per_share:0}}
struct F{bank:Session,shadow:Shadow,log:DispatchLog,path:PathBuf,seq:u64,bookseq:u64,rows:Vec<Value>}
impl Drop for F{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.path);}}
impl F{
 fn new()->Self{let path=std::env::temp_dir().join(format!("execution-distribution-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));std::fs::create_dir(&path).unwrap();let policy=json!({"initialCash":"100.000000","maximumCommitted":"40.000000","maximumMarketCost":"20.000000","quantity":4,"maximumMarkets":3,"minimumSpreadTicks":2,"entryStopAt":stamp(1_000_000)});let seed=json!({"runId":"distribution-fixture","availableCash":"100.000000","accountSnapshotHash":"a".repeat(64),"observedAt":stamp(0)});let bank=Session::open_live(&path.join("bank"),&policy,&seed).unwrap();let shadow=Shadow::new(&bank,config()).unwrap();let log=DispatchLog::open(&path.join("dispatch.ndjson")).unwrap();Self{bank,shadow,log,path,seq:0,bookseq:0,rows:Vec::new()}}
 fn put(&mut self,mut e:Value,at:u64){e["receivedAt"]=json!(stamp(at));e["processedAt"]=json!(stamp(at));self.seq+=1;self.bank.accept("moloch-live",self.seq,&e).unwrap();self.shadow.observe_committed(&self.bank,"moloch-live",self.seq,&e).unwrap();}
 fn coverage(&mut self,at:u64){let from=chrono::DateTime::from_timestamp_millis((BASE-1000)as i64).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true);self.put(json!({"type":"coverage","marketId":"101","exchangeId":"101","tournamentId":"cup","from":from,"to":stamp(at),"complete":true,"projectedThroughSequence":"999999"}),at);}
 fn book(&mut self,source:u64,observed:u64,bid:&str,ask:&str,depth:u64){self.bookseq+=1;self.put(json!({"type":"book","book":{"tournamentId":"cup","marketId":"101","exchangeId":"101","sequence":self.bookseq.to_string(),"sourceAt":stamp(source),"requestStartedAt":stamp(source),"receivedAt":stamp(observed),"bids":[{"price":bid,"quantity":depth}],"asks":[{"price":ask,"quantity":depth}]}}),observed);}
 fn quote(&self)->Value{self.bank.engine().order_records().into_iter().find(|q|q["retired"]==false&&q["exchangeId"]=="101"&&q["side"]=="YES"&&q["action"]=="buy"&&q["price"]=="0.400000").unwrap()}
 fn intent(&mut self,q:&Value,at:u64,carry:bool){self.intent_review(q,at,carry,None)}
 fn intent_review(&mut self,q:&Value,at:u64,carry:bool,maker_review:Option<&str>){let id=q["id"].as_u64().unwrap();let body=json!({"idempotencyKey":format!("distribution-fixture:{id}"),"tournamentId":"cup","exchangeId":q["exchangeId"],"side":if q["side"]=="NO"{"no"}else{"yes"},"action":q["action"],"quantity":q["quantity"],"price":serde_json::from_str::<Value>(q["price"].as_str().unwrap()).unwrap(),"expirationDate":chrono::DateTime::from_timestamp_millis(q["expiresAt"].as_i64().unwrap()).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true)});let spec=RequestSpec{method:"POST".into(),endpoint:"/orders".into(),body_json:Some(serde_json::to_string(&body).unwrap()),body:Some(body)};self.log.append(json!({"kind":"intent","qid":id,"quote":q,"spec":spec,"at":stamp(at),"maker":maker_review.map(|sha|json!({"reviewedSettingsSha256":sha})),"fundamental":if carry{json!({"binding":"synthetic carry tag"})}else{Value::Null}})).unwrap();self.log.append(json!({"kind":"attempt","qid":id,"at":stamp(at),"captureAtMs":BASE+at,"nativeHead":self.bank.durable_head(),"dispatchBefore":self.log.proof(id)})).unwrap();}
 fn start(&mut self)->Value{self.coverage(0);self.book(0,0,"0.400000","0.450000",100);self.coverage(3000);self.book(3000,3000,"0.400000","0.450000",100);let q=self.quote();self.intent(&q,3000,false);assert!(self.shadow.track_attempt(&self.bank,&self.log,q["id"].as_u64().unwrap(),BASE+3000).unwrap());q}
 fn r(endpoint:String,data:Value,start:u64,end:u64)->Receipt{Receipt{endpoint,request_started_at:stamp(start),received_at:stamp(end),status:200,data}}
 fn actual(q:&Value)->String{format!("90{}",q["id"].as_u64().unwrap())}
 fn ack(&mut self,q:&Value,at:u64){self.ack_quantity(q,at,q["quantity"].as_u64().unwrap())}
 fn ack_quantity(&mut self,q:&Value,at:u64,n:u64){let id=q["id"].as_u64().unwrap();let r=Self::r("/orders".into(),json!({"orderId":Self::actual(q),"exchangeId":q["exchangeId"],"side":if q["side"]=="NO"{"no"}else{"yes"},"action":q["action"],"price":serde_json::from_str::<Value>(q["price"].as_str().unwrap()).unwrap(),"quantity":n}),at-1,at);let e=feedback::acknowledgment(q,&r,&stamp(at)).unwrap();if self.log.attempted.contains(&id){self.log.append(json!({"kind":"ack","qid":id,"receipt":r})).unwrap();}self.put(e,at);}
 fn tape(&self,q:&Value,start:u64,end:u64)->Receipt{let total=self.rows.iter().map(|r|r["quantity"].as_i64().unwrap()).sum::<i64>();Self::r(format!("/orders/{}/fills?limit=200",Self::actual(q)),json!({"orderId":Self::actual(q),"exchangeId":q["exchangeId"],"tournamentId":"cup","coverage":{"complete":true,"projectedThroughSequence":9999},"pagination":{"hasMore":false,"nextCursor":null},"totalQuantityFilled":total,"data":self.rows}),start,end)}
 fn fill(&mut self,q:&Value,n:u64,price:f64,executed:u64,observed:u64,fillid:u64){self.rows.push(json!({"id":fillid,"quantity":if q["side"]=="NO"{-(n as i64)}else{n as i64},"side":if q["side"]=="NO"{"no"}else{"yes"},"price":price,"filledAt":stamp(executed)}));let tape=self.tape(q,observed-1,observed);for e in feedback::fills(q,&Self::actual(q),"cup",&tape,&stamp(observed)).unwrap(){self.put(e,observed);}}
 fn close(&mut self,q:&Value,start:u64,at:u64)->(Receipt,Receipt){let filled=self.rows.iter().map(|r|r["quantity"].as_i64().unwrap().unsigned_abs()).sum::<u64>();let order=Self::r(format!("/orders/{}",Self::actual(q)),json!({"id":Self::actual(q),"exchangeId":q["exchangeId"],"tournamentId":"cup","side":if q["side"]=="NO"{"no"}else{"yes"},"action":q["action"],"priceLimit":serde_json::from_str::<Value>(q["price"].as_str().unwrap()).unwrap(),"quantity":q["quantity"],"quantityFilled":filled,"open":false,"terminalReasonCode":"Canceled"}),start,start+1);let tape=self.tape(q,start+1,at);for e in feedback::fills(q,&Self::actual(q),"cup",&tape,&stamp(at)).unwrap(){self.put(e,at);}let e=feedback::terminal(q,&Self::actual(q),"cup",&order,&tape,&stamp(at)).unwrap().unwrap();self.put(e,at);self.log.append(json!({"kind":"closed","qid":q["id"]})).unwrap();(order,tape)}
 fn confirm(&mut self,q:&Value,start:u64,at:u64){let(o,t)=self.close(q,start,at);assert!(self.shadow.confirm_terminal(&self.bank,&self.log,q["id"].as_u64().unwrap(),&o,&t,BASE+at).unwrap());}
 fn mark(&mut self,at:u64,bid:&str,depth:u64){self.coverage(at);self.book(at,at,bid,"0.500000",depth);}
}

#[test]fn zero_is_only_a_closed_complete_original_lifecycle_and_has_zero_principal_pnl(){let mut f=F::new();let q=f.start();let id=q["id"].as_u64().unwrap();let before=f.shadow.outcome(id,BASE+3000).unwrap();assert_eq!(before.class,"unresolved");assert_eq!(before.conditional_gain_units,None);f.ack(&q,3100);f.confirm(&q,3150,3200);let out=f.shadow.outcome(id,BASE+3200).unwrap();assert_eq!(out.class,"confirmed_zero");assert_eq!(out.conditional_gain_units,Some(0));assert!(out.capital_time_complete);assert_eq!(out.reservation_capital_time_unit_ms,Some(4*400000*3200));let key=f.shadow.pool_key(id).unwrap();let e=f.shadow.estimate(key,"101",BASE+3200).unwrap();assert_eq!(e.parent_counts,[1,0,0]);assert_eq!(e.observed_joint_mean_per_requested_share,Some(0.));assert_eq!(e.tail_charge_per_requested_share,Some(0.));assert_eq!(e.mean_write_charge_per_requested_share,Some(25.));assert_eq!(e.shrunk_joint_mean_per_requested_share,None,"unseen partial/full conditional values are unknown, not positive pseudo-observations");assert!(!e.execution_authority);}
#[test]fn unknown_and_open_orders_never_become_zero_after_a_timeout(){let mut f=F::new();let q=f.start();let id=q["id"].as_u64().unwrap();f.put(json!({"type":"tick"}),20_000);let out=f.shadow.outcome(id,BASE+20_000).unwrap();assert_eq!(out.class,"unresolved");assert_eq!(out.conditional_gain_units,None);let e=f.shadow.estimate(f.shadow.pool_key(id).unwrap(),"101",BASE+20_000).unwrap();assert_eq!(e.parent_counts,[0,0,0]);assert_eq!(e.unresolved,1);assert_eq!(e.net_shadow_score_per_requested_share,None);}
#[test]fn partial_loss_is_quantity_weighted_not_charged_the_unfilled_principal(){let mut f=F::new();let q=f.start();let id=q["id"].as_u64().unwrap();f.ack(&q,3100);f.fill(&q,2,0.4,3500,3600,1001);f.confirm(&q,4000,4200);assert_eq!(f.shadow.outcome(id,BASE+4200).unwrap().conditional_gain_units,None);f.mark(4500,"0.390000",100);let out=f.shadow.outcome(id,BASE+4500).unwrap();assert_eq!(out.class,"confirmed_partial");assert_eq!(out.observed_filled_quantity,2);assert_eq!(out.conditional_gain_units,Some(-20000));assert_eq!(out.first_fill_latency_ms,Some(500));assert_eq!(out.maximum_receipt_delay_ms,Some(100));assert!(!out.capital_time_complete);assert_eq!(out.owned_capital_remaining_quantity,2);let e=f.shadow.estimate(f.shadow.pool_key(id).unwrap(),"101",BASE+4500).unwrap();assert_eq!(e.expected_filled_fraction,Some(0.5));assert_eq!(e.observed_joint_mean_per_requested_share,Some(-5000.));assert_eq!(e.conditional_per_filled_share,Some(-10000.));assert_eq!(e.capital_time_charge_per_requested_share,None,"hypothetical liquidation is not an actual capital release");}
#[test]fn complete_quantity_and_value_remain_distinct_from_actual_profit(){let mut f=F::new();let q=f.start();let id=q["id"].as_u64().unwrap();f.ack(&q,3100);f.fill(&q,4,0.4,3500,3600,1001);f.confirm(&q,4000,4200);f.mark(4500,"0.420000",100);let out=f.shadow.outcome(id,BASE+4500).unwrap();assert_eq!(out.class,"confirmed_full");assert_eq!(out.conditional_gain_units,Some(80000));assert_eq!(f.bank.engine().wallet.realized,0);assert_eq!(f.bank.engine().wallet.quantity("101",moloch_replay::Side::Yes),4);assert!(!out.capital_time_complete);}
#[test]fn delayed_observation_cannot_retroactively_use_an_already_observed_profitable_book(){let mut f=F::new();let q=f.start();let id=q["id"].as_u64().unwrap();f.ack(&q,3100);f.mark(4500,"0.480000",100);f.fill(&q,2,0.4,3500,5000,1001);f.confirm(&q,5100,5200);let out=f.shadow.outcome(id,BASE+5200).unwrap();assert_eq!(out.class,"confirmed_partial");assert_eq!(out.conditional_gain_units,None);assert_eq!(out.value_censored_quantity,2);assert_eq!(out.maximum_receipt_delay_ms,Some(1500));assert_eq!(f.shadow.diagnostic()["censorAndFeatureReasons"]["fill_observed_after_target"],1);}
#[test]fn first_shallow_mark_is_censored_instead_of_replaced_by_later_favorable_depth(){let mut f=F::new();let q=f.start();let id=q["id"].as_u64().unwrap();f.ack(&q,3100);f.fill(&q,4,0.4,3500,3600,1001);f.confirm(&q,4000,4200);f.mark(4500,"0.420000",1);f.mark(4600,"0.490000",100);assert_eq!(f.shadow.outcome(id,BASE+4600).unwrap().conditional_gain_units,None);assert_eq!(f.shadow.diagnostic()["censorAndFeatureReasons"]["insufficient_aggregate_depth"],1);}
#[test]fn simultaneous_fill_rows_share_depth_and_never_each_reuse_the_same_first_level(){let mut f=F::new();let q=f.start();let id=q["id"].as_u64().unwrap();f.ack(&q,3100);f.fill(&q,2,0.4,3500,3550,1001);f.fill(&q,2,0.4,3500,3600,1002);f.confirm(&q,4000,4200);f.mark(4500,"0.420000",2);let out=f.shadow.outcome(id,BASE+4500).unwrap();assert_eq!(out.observed_filled_quantity,4);assert_eq!(out.value_censored_quantity,4);assert_eq!(out.conditional_gain_units,None);}
#[test]fn source_gaps_and_old_source_clocks_cannot_create_a_conditional_value_label(){for stale in [false,true]{let mut f=F::new();let q=f.start();let id=q["id"].as_u64().unwrap();f.ack(&q,3100);f.fill(&q,2,0.4,3500,3600,1001);f.confirm(&q,4000,4200);if stale{f.coverage(4500);f.book(4500,6501,"0.490000","0.500000",100);}else{f.put(json!({"type":"gap","exchangeId":"101","marketId":"101","tournamentId":"cup"}),4300);f.mark(4500,"0.490000",100);}assert_eq!(f.shadow.outcome(id,BASE+if stale{6501}else{4500}).unwrap().conditional_gain_units,None);}}
#[test]fn known_own_remaining_bid_liquidity_is_not_a_counterfactual_exit(){let mut f=F::new();let q=f.start();let id=q["id"].as_u64().unwrap();f.ack(&q,3100);f.fill(&q,1,0.4,3500,3600,1001);f.mark(4500,"0.400000",3);f.confirm(&q,4600,4700);assert_eq!(f.shadow.outcome(id,BASE+4700).unwrap().conditional_gain_units,None);assert_eq!(f.shadow.diagnostic()["censorAndFeatureReasons"]["insufficient_aggregate_depth"],1);}
#[test]fn original_tape_and_committed_terminal_are_mandatory_not_an_ack_or_retired_flag(){let mut f=F::new();let q=f.start();let id=q["id"].as_u64().unwrap();f.ack(&q,3100);let(o,t)=f.close(&q,3150,3200);let mut bad=t.clone();bad.data["coverage"]["complete"]=json!(false);assert!(f.shadow.confirm_terminal(&f.bank,&f.log,id,&o,&bad,BASE+3200).is_err());assert_eq!(f.shadow.outcome(id,BASE+3200).unwrap().class,"unresolved");let mut wrong=o.clone();wrong.endpoint="/orders/999".into();assert!(f.shadow.confirm_terminal(&f.bank,&f.log,id,&wrong,&t,BASE+3200).is_err());assert!(f.shadow.confirm_terminal(&f.bank,&f.log,id,&o,&t,BASE+3200).unwrap());assert!(!f.shadow.confirm_terminal(&f.bank,&f.log,id,&o,&t,BASE+3200).unwrap());}
#[test]fn exact_membership_rejects_changed_prepared_bytes_and_policy_change(){let mut f=F::new();let mut event=json!({"type":"tick","receivedAt":stamp(0),"processedAt":stamp(0)});f.bank.accept("moloch-live",1,&event).unwrap();event["receivedAt"]=json!(stamp(1));assert_eq!(f.shadow.observe_committed(&f.bank,"moloch-live",1,&event),Err("DIST_SOURCE_MEMBERSHIP"));assert!(!f.shadow.diagnostic()["disabled"].is_null());}
#[test]fn repeated_full_tapes_do_not_double_count_fills_fifo_capital_or_samples(){let mut f=F::new();let q=f.start();let id=q["id"].as_u64().unwrap();f.ack(&q,3100);f.fill(&q,2,0.4,3500,3600,1001);let tape=f.tape(&q,3650,3700);for e in feedback::fills(&q,&F::actual(&q),"cup",&tape,&stamp(3700)).unwrap(){f.put(e,3700);}assert_eq!(f.shadow.outcome(id,BASE+3700).unwrap().owned_capital_remaining_quantity,2);f.confirm(&q,4000,4200);f.mark(4500,"0.420000",100);let e=f.shadow.estimate(f.shadow.pool_key(id).unwrap(),"101",BASE+4500).unwrap();assert_eq!(e.parent_counts,[0,1,0]);assert_eq!(e.observed_joint_mean_per_requested_share,Some(10000.));assert!(f.shadow.diagnostic()["duplicateEvents"].as_u64().unwrap()>=2);}
#[test]fn carry_tagged_original_attempts_never_pollute_short_horizon_distribution(){let mut f=F::new();f.coverage(0);f.book(0,0,"0.400000","0.450000",100);f.book(3000,3000,"0.400000","0.450000",100);let q=f.quote();f.intent(&q,3000,true);assert!(!f.shadow.track_attempt(&f.bank,&f.log,q["id"].as_u64().unwrap(),BASE+3000).unwrap());assert!(f.shadow.pool_key(q["id"].as_u64().unwrap()).is_none());assert_eq!(f.shadow.diagnostic()["excludedFundamentalCarry"],1);}
#[test]fn actual_opposite_buy_redemption_ends_owned_capital_without_a_markout_assumption(){let mut f=F::new();let q=f.start();let id=q["id"].as_u64().unwrap();f.ack(&q,3100);f.fill(&q,2,0.4,3500,3600,1001);f.confirm(&q,4000,4200);let hedge=f.bank.engine().order_records().into_iter().find(|q|q["retired"]==false&&q["side"]=="NO"&&q["action"]=="buy").expect("actual opposite native quote");f.ack(&hedge,4300);let n=2;let e=json!({"type":"actual_fill","source":"official_sig_api_v1","receiptHash":"d".repeat(64),"orderId":hedge["id"],"actualOrderId":F::actual(&hedge),"exchangeId":"101","marketId":"101","side":"NO","action":"buy","quantity":n,"price":hedge["price"],"fee":"0.000000","fillId":"9001","executedAt":stamp(4400)});f.put(e.clone(),4450);let out=f.shadow.outcome(id,BASE+4450).unwrap();assert!(out.capital_time_complete);assert_eq!(out.owned_capital_remaining_quantity,0);assert_eq!(out.owned_capital_time_observed_unit_ms,2*400000*900);f.put(e,4460);assert_eq!(f.shadow.outcome(id,BASE+4460).unwrap().owned_capital_time_observed_unit_ms,out.owned_capital_time_observed_unit_ms,"untracked duplicate hedge fills must not consume FIFO again");}
#[test]fn current_sdk_owned_fills_endpoint_is_exact_and_scope_stays_in_original_data(){let mut f=F::new();let q=f.start();let id=q["id"].as_u64().unwrap();f.ack(&q,3100);let(o,t)=f.close(&q,3150,3200);assert_eq!(t.endpoint,format!("/orders/{}/fills?limit=200",F::actual(&q)));let mut invented=t.clone();invented.endpoint.push_str("&tournamentId=cup");assert_eq!(f.shadow.confirm_terminal(&f.bank,&f.log,id,&o,&invented,BASE+3200),Err("DIST_ORIGINAL_CLOSE_ENDPOINT"));assert!(f.shadow.confirm_terminal(&f.bank,&f.log,id,&o,&t,BASE+3200).unwrap());}
#[test]fn original_receipt_clock_is_preserved_when_actual_terminal_processing_finishes_later(){let mut f=F::new();let q=f.start();let id=q["id"].as_u64().unwrap();f.ack(&q,3100);let(o,t)=f.close(&q,3150,3200);let mut prepared=feedback::terminal(&q,&F::actual(&q),"cup",&o,&t,&stamp(3200)).unwrap().unwrap();prepared["processedAt"]=json!(stamp(3217));f.seq+=1;f.bank.accept("moloch-live",f.seq,&prepared).unwrap();f.shadow.observe_committed(&f.bank,"moloch-live",f.seq,&prepared).unwrap();assert_eq!(prepared["receivedAt"],t.received_at);assert!(f.shadow.confirm_terminal(&f.bank,&f.log,id,&o,&t,BASE+3217).unwrap());assert_eq!(f.shadow.outcome(id,BASE+3217).unwrap().conditional_gain_units,Some(0));}
#[test]fn normalized_parent_pool_shrinks_market_counts_without_treating_same_time_races_as_independent_blocks(){
 let mut f=F::new();f.coverage(0);f.book(0,0,"0.400000","0.450000",100);let other=|sequence:u64,at:u64|json!({"type":"book","book":{"tournamentId":"cup","marketId":"102","exchangeId":"102","sequence":sequence.to_string(),"sourceAt":stamp(at),"requestStartedAt":stamp(at),"receivedAt":stamp(at),"bids":[{"price":"0.420000","quantity":100}],"asks":[{"price":"0.470000","quantity":100}]}});f.put(other(1,0),0);f.coverage(3000);f.book(3000,3000,"0.400000","0.450000",100);f.put(other(2,3000),3000);f.put(json!({"type":"tick"}),7000);
 let q=f.quote();f.intent(&q,7000,false);let id=q["id"].as_u64().unwrap();f.shadow.track_attempt(&f.bank,&f.log,id,BASE+7000).unwrap();let key=f.shadow.pool_key(id).unwrap().clone();f.ack(&q,7010);
 let q2=f.bank.engine().order_records().into_iter().find(|q|q["exchangeId"]=="102"&&q["side"]=="YES"&&q["action"]=="buy"&&q["retired"]==false).unwrap();f.intent(&q2,7010,false);let id2=q2["id"].as_u64().unwrap();f.shadow.track_attempt(&f.bank,&f.log,id2,BASE+7010).unwrap();assert_eq!(f.shadow.pool_key(id2),Some(&key),"exact exchange and absolute limit remain provenance, not the statistical pooling boundary");f.ack(&q2,7020);f.confirm(&q,7100,7200);f.confirm(&q2,7300,7400);
 let e=f.shadow.estimate(&key,"101",BASE+7400).unwrap();assert_eq!(e.parent_completed,2);assert_eq!(e.market_completed,1);assert_eq!(e.distinct_markets,2);assert_eq!(e.time_blocks,1);assert_eq!(e.parent_counts,[2,0,0]);assert_eq!(e.market_counts,[1,0,0]);assert!((e.posterior_zero_partial_full[0]-0.68).abs()<1e-12);assert!(!e.qualified_descriptive_sample);assert_eq!(e.empirical_block_standard_error,None);assert_eq!(e.net_shadow_score_per_requested_share,None);assert_eq!(e.minimum_observed_per_requested_share,Some(0.));assert!(!e.independent_censoring_assumed);
}
#[test]fn cancellation_ack_does_not_hide_a_later_official_partial_fill_or_become_zero(){let mut f=F::new();let q=f.start();let id=q["id"].as_u64().unwrap();f.ack(&q,3100);f.log.append(json!({"kind":"cancel_attempt","qid":id,"at":stamp(3200)})).unwrap();f.log.append(json!({"kind":"cancel_ack","qid":id,"receipt":F::r(format!("/orders/{}",F::actual(&q)),json!({"orderId":F::actual(&q),"tournamentId":"cup"}),3200,3300)})).unwrap();assert_eq!(f.shadow.outcome(id,BASE+3300).unwrap().class,"unresolved");f.fill(&q,1,0.4,3350,3400,1001);f.confirm(&q,3500,3600);assert_eq!(f.shadow.outcome(id,BASE+3600).unwrap().class,"confirmed_partial");assert_eq!(f.shadow.outcome(id,BASE+3600).unwrap().observed_filled_quantity,1);}
#[test]fn actual_smaller_admission_is_partial_requested_execution_and_releases_rejected_reservation_at_ack(){let mut f=F::new();let q=f.start();let id=q["id"].as_u64().unwrap();f.ack_quantity(&q,3100,2);f.fill(&q,2,0.4,3500,3600,1001);let admitted=f.bank.engine().order_records().into_iter().find(|q|q["id"]==id).unwrap();assert_eq!(admitted["quantity"],2);f.confirm(&admitted,4000,4200);let out=f.shadow.outcome(id,BASE+4200).unwrap();assert_eq!(out.class,"confirmed_partial");assert_eq!(out.requested_quantity,4);assert_eq!(out.admitted_quantity,Some(2));assert_eq!(out.reservation_capital_time_unit_ms,Some(4*400000*3100+2*400000*400));}
#[test]fn actual_maker_review_versions_are_not_pooled_even_for_identical_normalized_quotes(){let mut keys=Vec::new();for review in ["a".repeat(64),"b".repeat(64)]{let mut f=F::new();f.coverage(0);f.book(0,0,"0.400000","0.450000",100);f.book(3000,3000,"0.400000","0.450000",100);let q=f.quote();f.intent_review(&q,3000,false,Some(&review));let id=q["id"].as_u64().unwrap();f.shadow.track_attempt(&f.bank,&f.log,id,BASE+3000).unwrap();keys.push(f.shadow.pool_key(id).unwrap().clone());}assert_eq!(keys[0].policy_sha256,keys[1].policy_sha256);assert_ne!(keys[0].strategy_sha256,keys[1].strategy_sha256);}
#[test]fn aged_confirmed_owned_cohort_is_reclaimed_only_after_actual_fifo_close(){
 let mut f=F::new();let mut cfg=config();cfg.retained_samples=2;cfg.maximum_pending=2;f.shadow=Shadow::new(&f.bank,cfg).unwrap();
 let q=f.start();let id=q["id"].as_u64().unwrap();f.ack(&q,3100);f.fill(&q,2,0.4,3500,3600,1001);f.confirm(&q,4000,4200);f.rows.clear();
 for (ex,at) in [("102",8000),("103",13000)]{
  for(seq,t)in [(1,at-3000),(2,at)]{f.put(json!({"type":"book","book":{"tournamentId":"cup","marketId":ex,"exchangeId":ex,"sequence":seq.to_string(),"sourceAt":stamp(t),"requestStartedAt":stamp(t),"receivedAt":stamp(t),"bids":[{"price":"0.420000","quantity":100}],"asks":[{"price":"0.470000","quantity":100}]}}),t);}
  let other=f.bank.engine().order_records().into_iter().find(|v|v["retired"]==false&&v["exchangeId"]==ex&&v["side"]=="YES"&&v["action"]=="buy").unwrap();let otherid=other["id"].as_u64().unwrap();f.intent(&other,at,false);assert!(f.shadow.track_attempt(&f.bank,&f.log,otherid,BASE+at).unwrap());f.ack(&other,at+10);f.confirm(&other,at+100,at+200);
 }
 assert_eq!(f.shadow.diagnostic()["tracked"],3);assert_eq!(f.shadow.outcome(id,BASE+13200).unwrap().owned_capital_remaining_quantity,2);
 let hedge=f.bank.engine().order_records().into_iter().find(|v|v["exchangeId"]=="101"&&v["retired"]==false&&v["side"]=="NO"&&v["action"]=="buy").unwrap();f.ack(&hedge,13300);
 let event=json!({"type":"actual_fill","source":"official_sig_api_v1","receiptHash":"d".repeat(64),"orderId":hedge["id"],"actualOrderId":F::actual(&hedge),"exchangeId":"101","marketId":"101","side":"NO","action":"buy","quantity":2,"price":hedge["price"],"fee":"0.000000","fillId":"9001","executedAt":stamp(13400),"receivedAt":stamp(13450),"processedAt":stamp(13450)});
 f.seq+=1;f.bank.accept("moloch-live",f.seq,&event).unwrap();let financial=f.bank.engine().report().unwrap();let head=f.bank.durable_head();f.shadow.observe_committed(&f.bank,"moloch-live",f.seq,&event).unwrap();
 assert_eq!(f.shadow.diagnostic()["tracked"],2);assert!(f.shadow.outcome(id,BASE+13450).is_err());assert_eq!(f.bank.engine().report().unwrap(),financial);assert_eq!(f.bank.durable_head(),head);assert_eq!(f.shadow.diagnostic()["disabled"],Value::Null);
}

fn query_action(q:&Value)->Value{json!({"exchangeId":q["exchangeId"],"marketId":q["marketId"],"tournamentId":"cup","side":if q["side"]=="NO"{"no"}else{"yes"},"action":"buy","quantity":q["quantity"],"limitPrice":q["price"]})}
fn query_scope()->baal_transport_service::Scope{baal_transport_service::Scope{tournament_id:"cup".into(),tournament_slug:"cup".into(),exchanges:[("101".into(),"101".into())].into()}}
#[test]fn prospective_query_reuses_genuine_configured_features_without_creating_an_exposure(){let mut f=F::new();let q=f.start();let id=q["id"].as_u64().unwrap();let key=f.shadow.pool_key(id).unwrap().clone();let before=f.shadow.diagnostic();let head=f.bank.durable_head();let e=f.shadow.estimate_action(&f.bank,&query_scope(),&query_action(&q),&key.strategy_sha256,q["createdAt"].as_u64().unwrap(),q["expiresAt"].as_u64().unwrap(),1000,BASE+3000).unwrap();assert_eq!(e.pool_key,key);assert_eq!(e.unresolved,1);assert_eq!(e.parent_completed,0);assert_eq!(e.net_shadow_score_per_requested_share,None);assert_eq!(f.shadow.diagnostic(),before);assert_eq!(f.bank.durable_head(),head);}
#[test]fn prospective_short_markout_cannot_be_used_as_terminal_or_new_strategy_evidence(){let mut f=F::new();let q=f.start();let key=f.shadow.pool_key(q["id"].as_u64().unwrap()).unwrap();let a=query_action(&q);let t=q["expiresAt"].as_u64().unwrap();assert_eq!(f.shadow.estimate_action(&f.bank,&query_scope(),&a,&key.strategy_sha256,BASE,t,300000,BASE+3000).unwrap_err(),"DIST_QUERY_HORIZON_MISMATCH");assert_eq!(f.shadow.estimate_action(&f.bank,&query_scope(),&a,&"a".repeat(64),BASE,t,1000,BASE+3000).unwrap_err(),"DIST_QUERY_STRATEGY_UNOBSERVED");}
#[test]fn prospective_query_does_not_reuse_passive_samples_for_aggressive_or_foreign_action(){let mut f=F::new();let q=f.start();let key=f.shadow.pool_key(q["id"].as_u64().unwrap()).unwrap().clone();let mut a=query_action(&q);let t=q["expiresAt"].as_u64().unwrap();a["limitPrice"]=json!("0.450000");assert_eq!(f.shadow.estimate_action(&f.bank,&query_scope(),&a,&key.strategy_sha256,BASE,t,1000,BASE+3000).unwrap_err(),"DIST_FEATURE_NOT_DISPLAYED_PASSIVE");a=query_action(&q);a["tournamentId"]=json!("foreign");assert_eq!(f.shadow.estimate_action(&f.bank,&query_scope(),&a,&key.strategy_sha256,BASE,t,1000,BASE+3000).unwrap_err(),"DIST_QUERY_SCOPE");}
#[test]fn bank_events_not_observed_by_the_execution_model_block_prospective_estimation(){let mut f=F::new();let q=f.start();let key=f.shadow.pool_key(q["id"].as_u64().unwrap()).unwrap().clone();f.seq+=1;f.bank.accept("moloch-live",f.seq,&json!({"type":"tick","receivedAt":stamp(3001),"processedAt":stamp(3001)})).unwrap();assert_eq!(f.shadow.estimate_action(&f.bank,&query_scope(),&query_action(&q),&key.strategy_sha256,BASE,q["expiresAt"].as_u64().unwrap(),1000,BASE+3001).unwrap_err(),"DIST_QUERY_OBSERVER_NOT_CURRENT");}
